import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ conversations, onSelectConversation }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [user, setUser] = useState(null);

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
    console.log("Logged-in user from localStorage:", storedUser);
  }, []);

  const handleSearch = async () => {
    try {
      console.log("🔍 Searching by username with keywords:", searchTerm);
      const token = localStorage.getItem("token");

      const response = await axios.get(
        `http://localhost:5000/api/profile/search?username=${searchTerm}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log("🔁 # of users found:", response.data.length);
      setSearchResults(response.data);
    } catch (error) {
      console.error("❌ Error searching users:", error);
    }
  };

  return (
    <div className="chat-sidebar">
      <h3>Messages</h3>

      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search by username..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>

      {/* Search Results */}
      {searchResults.length > 0 && (
        <div className="search-results">
          {searchResults.map((result) => (
            <div
              key={result.userId._id}
              className="search-result"
              onClick={() => onSelectConversation(result.userId)}
            >
              {result.userId.username}
            </div>
          ))}
        </div>
      )}

      {/* Conversation List */}
      {conversations && conversations.length > 0 ? (
        conversations.map((conv) => (
          <div key={conv._id} onClick={() => onSelectConversation(conv)}>
            {conv.participantUsernames.find((name) => name !== user?.username)}
            <br />
            <small>{conv.lastMessage}</small>
          </div>
        ))
      ) : (
        <p>No conversations found.</p>
      )}
    </div>
  );
};

export default ChatSidebar;
